        a=json.loads(line); title=a.get('title') or ''
        if title in seen: continue
        seen.add(title)
        if any(x in title.lower() for x in ['full transcript','transcript:','live updates']):
            continue
        arts.append((title, a.get('source') or '', toks(title)))
hits=[]
for qid,title,qt,pred in qs:
    best=[]
    for atitle,src,at in arts:
        inter=qt & at
        if len(inter)>=2 and any(len(t)>=5 for t in inter):
            best.append((len(inter), atitle, src, ', '.join(sorted(inter))))
